(function(){
'use strict';

const TEAMS_URL='ffws-br-2026-s2/teams.json';
const QUALIFIED=['LOS','LOUD SNICKERS','FLUXO W7M','INTZ','TEAM SOLID','RISE GAMING','ALPHA7','RUSH GAMING','INFLUENCE RAGE','CPT VOX','AFROGAMES','SX TET'];
const LOCAL_TEAM_LOGOS={AFROGAMES:'home-assets/teams/afrogames.webp',ALPHA7:'home-assets/teams/alpha7.webp',CIVIS:'home-assets/teams/civis.webp',CPTVOX:'home-assets/teams/cpt-vox.webp',FLUXOW7M:'home-assets/teams/fluxo-w7m.webp',INFLUENCERAGE:'home-assets/teams/influence-rage.webp',INTZ:'home-assets/teams/intz.webp',LOOPS:'home-assets/teams/loops.webp',LOS:'home-assets/teams/los.webp',LOUDSNICKERS:'home-assets/teams/loud-snickers.webp',RISEGAMING:'home-assets/teams/rise-gaming.webp',RUSHGAMING:'home-assets/teams/rush-gaming.webp',SXTET:'home-assets/teams/sx-tet.webp',TEAMSOLID:'home-assets/teams/team-solid.webp'};
const HOME_TEAM_SHORTS={AFROGAMES:'AFG',CIVIS:'CTZ',INFLUENCERAGE:'INF',LOOPS:'LPS',SXTET:'SX'};
const CHANNEL_URL='https://www.youtube.com/@ffesportsbr';
const FALLBACK_START='2026-08-01';
const FALLBACK_END='2026-10-11';
const DEFAULT_LIVE_START='12:50';
const DEFAULT_LIVE_END='16:05';
let teams=[];
let competitionSchedule=[];
let broadcasts=fallbackSchedule();
let lastAutomaticContext='';
let manualRoundOverride=false;
let state={roundLabel:'Segunda Fase • Rodada 1 • 19/09 • 13h',restingTeams:[]};

function normalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase()}
function esc(value){return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function pad(value){return String(Math.max(0,Number(value)||0)).padStart(2,'0')}
function setText(id,value){const el=document.getElementById(id);if(el)el.textContent=value}
function timestampAt(date,time){const iso=String(date||'');const hhmm=/^\d{2}:\d{2}$/.test(String(time||''))?String(time):'13:00';const parsed=Date.parse(`${iso}T${hhmm}:00-03:00`);return Number.isFinite(parsed)?parsed:0}
function scheduleTimestamp(item){if(Number.isFinite(item&&item.timestamp))return item.timestamp;return timestampAt(item&&item.date,item&&item.time24||'13:00')}
function liveWindow(item){const date=String(item&&item.date||'');const startTime=String(item&&item.liveStart24||DEFAULT_LIVE_START);const endTime=String(item&&item.liveEnd24||DEFAULT_LIVE_END);let start=timestampAt(date,startTime),end=timestampAt(date,endTime);if(!start)start=scheduleTimestamp(item);if(!end||end<=start)end=start+(3*60+15)*60*1000;return {start,end,startTime,endTime}}
function formatDate(timestamp){return new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(timestamp)).replace(/^./,letter=>letter.toUpperCase())+' (BRT)'}
function formatLiveDate(item,windowInfo){const date=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'2-digit',month:'long'}).format(new Date(windowInfo.start)).replace(/^./,letter=>letter.toUpperCase());return `${date} • ${windowInfo.startTime}–${windowInfo.endTime} (BRT)`}
function fallbackSchedule(){const dates=[];const start=new Date(FALLBACK_START+'T00:00:00Z');const end=new Date(FALLBACK_END+'T00:00:00Z');let round=0;for(let current=new Date(start);current<=end;current.setUTCDate(current.getUTCDate()+1)){const day=current.getUTCDay();if(day!==0&&day!==6)continue;round++;const iso=current.toISOString().slice(0,10);dates.push({key:'fallback-'+iso,stage:'',stageName:'FFWS Brasil 2026 S2',label:'Dia '+round,round,date:iso,dateLabel:iso.slice(8,10)+'/'+iso.slice(5,7),time:'13h',time24:'13:00',liveStart24:DEFAULT_LIVE_START,liveEnd24:DEFAULT_LIVE_END,restingTeams:[],timestamp:timestampAt(iso,'13:00')})}return dates}
function stageKicker(item){const stage=String(item&&item.stage||'');if(stage==='classificatoria')return 'FFWS BRASIL 2026 S2 • CLASSIFICATÓRIA';if(stage==='segundaFase')return 'FFWS BRASIL 2026 S2 • SEGUNDA FASE';if(stage==='final')return 'FFWS BRASIL 2026 S2 • GRANDE FINAL';return 'FFWS BRASIL 2026 S2'}
function liveDayLabel(item){const round=Number(item&&item.round);if(Number.isFinite(round)&&round>0)return `DIA ${round}`;const label=String(item&&item.label||'').match(/(?:rodada|dia)\s*(\d+)/i);return label?`DIA ${label[1]}`:'TRANSMISSÃO AO VIVO'}
function roundLabel(item){if(!item)return 'Segunda Fase';const stage=String(item.stageName||'').trim();const label=String(item.label||'').trim();const date=String(item.dateLabel||'').trim();const time=String(item.time||'').trim();return [stage,label,date,time].filter(Boolean).join(' • ')}
function sameTeamList(a,b){const left=(a||[]).map(normalize).sort();const right=(b||[]).map(normalize).sort();return left.length===right.length&&left.every((value,index)=>value===right[index])}
function applyAutomaticRoundContext(item){if(manualRoundOverride)return;const nextResting=item&&item.stage==='classificatoria'&&Array.isArray(item.restingTeams)?item.restingTeams:[];const nextLabel=item?roundLabel(item):'Temporada encerrada';const key=item&&item.key?String(item.key):'season-ended';const changed=lastAutomaticContext!==key||state.roundLabel!==nextLabel||!sameTeamList(state.restingTeams,nextResting);if(!changed)return;lastAutomaticContext=key;state.roundLabel=nextLabel;state.restingTeams=[...nextResting];if(teams.length)renderTeams()}
function updateTimer(){const card=document.getElementById('home-s2-broadcast');if(!card)return;const now=Date.now();const liveItem=broadcasts.find(item=>{const w=liveWindow(item);return now>=w.start&&now<w.end});const nextItem=broadcasts.find(item=>liveWindow(item).start>now);const contextItem=liveItem||nextItem||null;applyAutomaticRoundContext(contextItem);const clock=document.getElementById('home-s2-broadcast-clock');const livePill=document.getElementById('home-s2-live-pill');const watch=document.getElementById('home-s2-watch');if(watch)watch.href=CHANNEL_URL;
if(liveItem){const windowInfo=liveWindow(liveItem);card.classList.add('is-live');if(clock)clock.hidden=true;if(livePill){livePill.hidden=false;livePill.textContent='AO VIVO AGORA'}setText('home-s2-broadcast-kicker',stageKicker(liveItem));setText('home-s2-broadcast-title',liveDayLabel(liveItem));setText('home-s2-broadcast-date',formatLiveDate(liveItem,windowInfo));if(watch)watch.textContent='ASSISTIR TRANSMISSÃO →';return}
card.classList.remove('is-live');if(clock)clock.hidden=false;if(livePill)livePill.hidden=true;if(!nextItem){setText('home-s2-broadcast-kicker','FFWS BRASIL 2026 S2');setText('home-s2-broadcast-title','TEMPORADA ENCERRADA');setText('home-s2-broadcast-date','Transmissões realizadas de 1º de agosto a 11 de outubro de 2026');setText('home-s2-days','00');setText('home-s2-hours','00');setText('home-s2-minutes','00');if(watch)watch.textContent='VER CANAL →';return}
const nextWindow=liveWindow(nextItem);const remaining=Math.max(0,nextWindow.start-now);const days=Math.floor(remaining/86400000);const hours=Math.floor((remaining%86400000)/3600000);const minutes=Math.floor((remaining%3600000)/60000);setText('home-s2-broadcast-kicker',stageKicker(nextItem));setText('home-s2-broadcast-title','PRÓXIMA TRANSMISSÃO');setText('home-s2-broadcast-date',formatDate(nextWindow.start));setText('home-s2-days',pad(days));setText('home-s2-hours',pad(hours));setText('home-s2-minutes',pad(minutes));if(watch)watch.textContent='VER CANAL →'}
function resolveLogo(team){const local=LOCAL_TEAM_LOGOS[normalize(team&&team.name)];if(local)return local;if(team.logo&&team.logo!=='escudo.webp')return team.logo;if(typeof window.getTeamLogoByAliases==='function'){const resolved=window.getTeamLogoByAliases(team.name);if(resolved&&resolved!=='escudo.webp')return resolved}if(typeof window.logos==='object'&&window.logos){const key=Object.keys(window.logos).find(name=>normalize(name)===normalize(team.name));if(key&&window.logos[key])return window.logos[key]}return 'escudo.webp'}
function openTeam(name){if(typeof window.openCurrentSeasonTeam==='function'){window.openCurrentSeasonTeam(name);return}window.location.href='equipe.html?time='+encodeURIComponent(name)}
function injectPhaseStyles(){if(document.getElementById('home-s2-second-phase-styles'))return;const style=document.createElement('style');style.id='home-s2-second-phase-styles';style.textContent=`
#home .home-rank-world-row td{background:linear-gradient(90deg,rgba(255,194,38,.15),rgba(255,194,38,.055))!important;border-bottom-color:rgba(255,194,38,.18)!important}
#home .home-rank-world-row td:first-child{box-shadow:inset 3px 0 #ffc226}
#home .home-rank-world-row .home-rank-pos,#home .home-rank-world-row .home-rank-points{color:#ffd45a!important}
#home .home-rank-world-row .home-rank-main small{color:#c7a84a!important}
#home #home-s2-resting-note.is-world-note{color:#ffd45a;font-weight:950}
#home .home-center-column .home-s2-team-grid{grid-template-columns:repeat(6,minmax(0,1fr))}
#ffws-br-s2-segunda-fase .ffws-s2-row-world td{background:linear-gradient(90deg,rgba(255,194,38,.13),rgba(255,194,38,.045))!important;border-bottom-color:rgba(255,194,38,.18)!important}
#ffws-br-s2-segunda-fase .ffws-s2-row-world td:first-child{box-shadow:inset 4px 0 #ffc226;color:#ffd45a!important}
@media(max-width:620px){#home .home-center-column .home-s2-team-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
`;document.head.appendChild(style)}
function tuneParticipantsHeader(){const head=document.querySelector('#home-s2-broadcast .home-s2-participants-head strong');if(head)head.textContent='12 TIMES CLASSIFICADOS';const grid=document.getElementById('home-s2-team-grid');if(grid)grid.setAttribute('aria-label','12 times classificados para a Segunda Fase da WB 2026 S2')}
function renderTeams(){const root=document.getElementById('home-s2-team-grid');if(!root)return;tuneParticipantsHeader();const resting=new Set((state.restingTeams||[]).map(normalize));root.innerHTML=teams.map(team=>{const isResting=resting.has(normalize(team.name));return `<button type="button" class="home-s2-team${isResting?' is-resting':''}" data-home-s2-team="${esc(team.name)}" aria-label="${esc(team.name)}${isResting?' — descansa nesta rodada':''}"><img decoding="async" loading="lazy" width="128" height="128" src="${esc(resolveLogo(team))}" alt="${esc(team.name)}" onerror="this.onerror=null;this.src='escudo.webp'"><strong title="${esc(team.name)}">${esc(HOME_TEAM_SHORTS[normalize(team.name)]||team.abbreviation||team.name)}</strong></button>`}).join('');root.querySelectorAll('[data-home-s2-team]').forEach(button=>button.addEventListener('click',()=>openTeam(button.getAttribute('data-home-s2-team'))));const note=document.getElementById('home-s2-resting-note');if(note){if(resting.size){note.hidden=false;note.classList.remove('is-world-note');note.textContent='Folga: '+(state.restingTeams||[]).map(name=>HOME_TEAM_SHORTS[normalize(name)]||name).join(' e ')}else{note.hidden=false;note.textContent='1º e 2º da Segunda Fase garantem vaga direta no Mundial';note.classList.add('is-world-note')}}setText('home-s2-round-label',state.roundLabel||'Segunda Fase')}
async function loadTeams(){try{const response=await fetch(`${TEAMS_URL}?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const payload=await response.json();const allTeams=Array.isArray(payload.teams)?payload.teams:[];const byName=new Map(allTeams.map(team=>[normalize(team.name),team]));teams=QUALIFIED.map(name=>byName.get(normalize(name))).filter(Boolean);competitionSchedule=Array.isArray(payload.schedule)?payload.schedule:[];if(!competitionSchedule.length){try{const scheduleResponse=await fetch(`ffws-br-2026-s2/dates.json?v=${Date.now()}`,{cache:'no-store'});if(scheduleResponse.ok){const schedulePayload=await scheduleResponse.json();competitionSchedule=Array.isArray(schedulePayload.rounds)?schedulePayload.rounds:[]}}catch(_){}}
if(competitionSchedule.length){broadcasts=competitionSchedule.map(item=>({...item,timestamp:scheduleTimestamp(item)})).filter(item=>item.timestamp).sort((a,b)=>liveWindow(a).start-liveWindow(b).start);lastAutomaticContext='';updateTimer()}renderTeams();if(typeof window.loadTeamLogos==='function'){Promise.resolve(window.loadTeamLogos()).then(()=>renderTeams()).catch(()=>{})}else setTimeout(renderTeams,900)}catch(error){const root=document.getElementById('home-s2-team-grid');if(root)root.innerHTML='<div class="home-s2-team-loading">Não foi possível carregar as equipes agora.</div>';console.error('[Home FFWS S2] Equipes:',error)}}
window.setHomeRestingTeams=function(restingTeams,roundText){manualRoundOverride=true;state.restingTeams=Array.isArray(restingTeams)?restingTeams:[];if(roundText)state.roundLabel=String(roundText);renderTeams()};
window.setHomeFFWSS2Round=function(config){const next=config&&typeof config==='object'?config:{};manualRoundOverride=true;state.restingTeams=Array.isArray(next.restingTeams)?next.restingTeams:state.restingTeams;state.roundLabel=next.roundLabel||next.label||state.roundLabel;renderTeams()};
window.clearHomeFFWSS2RoundOverride=function(){manualRoundOverride=false;lastAutomaticContext='';updateTimer()};
function boot(){injectPhaseStyles();tuneParticipantsHeader();updateTimer();loadTeams();window.setInterval(updateTimer,30000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
